import React, { useState, useEffect } from 'react';
import QRCode from 'react-qr-code';

const UPIQRCode = ({ amount, orderId }) => {
  const [upiId] = useState('amrutanshu20003-16@oksbi');
  const [qrValue, setQrValue] = useState('');
  const [countdown, setCountdown] = useState(300);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const upiString = `upi://pay?pa=${upiId}&pn=MilkMitra&am=${amount}&cu=INR&tn=Order_${orderId}`;
    setQrValue(upiString);
  }, [amount, orderId, upiId]);

  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [countdown]);

  useEffect(() => {
    // Prevent scroll
    document.body.style.overflow = 'hidden';

    // Disable navbar interactions
    const navbar = document.querySelector('nav, header, .navbar, [class*="nav"]');
    if (navbar) {
      navbar.style.pointerEvents = 'none';
      navbar.style.opacity = '0.5';
    }

    // Disable all interactive elements except our modal
    const allElements = document.querySelectorAll('button, a, input, select, textarea');
    allElements.forEach(el => {
      if (!el.closest('.fixed')) { // Don't disable elements inside our modal
        el.style.pointerEvents = 'none';
      }
    });

    return () => {
      document.body.style.overflow = '';
      if (navbar) {
        navbar.style.pointerEvents = '';
        navbar.style.opacity = '';
      }
      allElements.forEach(el => {
        el.style.pointerEvents = '';
      });
    };
  }, []);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(upiId);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-md flex items-center justify-center z-[9999] p-4">
      <div className="bg-white rounded-3xl p-8 max-w-lg w-full mx-auto shadow-2xl">
        {/* Header - No close button */}
        <div className="text-center mb-8">
          <div className="w-16 h-16 mx-auto mb-4 bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl flex items-center justify-center">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-gray-900">Complete Your Payment</h2>
          <p className="text-gray-500 mt-1">Order #{orderId?.slice(-8)?.toUpperCase()}</p>
        </div>

        {/* Amount */}
        <div className="text-center mb-8">
          <div className="text-5xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
            ₹{amount}
          </div>
        </div>

        {/* QR Code with glow effect */}
        <div className="flex justify-center mb-8">
          <div className="relative">
            <div className="absolute inset-0 bg-gradient-to-r from-blue-400 to-purple-400 rounded-3xl blur-xl opacity-20"></div>
            <div className="relative bg-white p-6 rounded-3xl border-2 border-gray-100 shadow-xl">
              {qrValue && (
                <QRCode
                  value={qrValue}
                  size={200}
                  level="H"
                  bgColor="#FFFFFF"
                  fgColor="#000000"
                />
              )}
            </div>
          </div>
        </div>

        {/* UPI ID */}
        <div className="bg-gray-50 rounded-2xl p-5 mb-6">
          <div className="text-sm text-gray-600 mb-3 text-center font-medium">Pay directly to UPI ID</div>
          <div className="flex items-center gap-3">
            <code className="flex-1 bg-white px-4 py-3 rounded-xl text-base font-mono text-gray-800 border-2 border-gray-200 text-center">
              {upiId}
            </code>
            <button
              onClick={handleCopy}
              className={`px-4 py-3 rounded-xl font-medium transition-all ${
                copied 
                  ? 'bg-green-500 text-white' 
                  : 'bg-blue-500 text-white hover:bg-blue-600'
              }`}
            >
              {copied ? '✓' : 'Copy'}
            </button>
          </div>
        </div>

        {/* Instructions */}
        <div className="bg-gradient-to-br from-blue-50 to-purple-50 rounded-2xl p-5 mb-6">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center">
              <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
              </svg>
            </div>
            <span className="font-semibold text-gray-800">How to Pay</span>
          </div>
          <ol className="text-sm text-gray-700 space-y-2">
            <li className="flex items-start gap-2">
              <span className="w-5 h-5 bg-blue-500 text-white rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">1</span>
              <span>Open any UPI app (Google Pay, PhonePe, Paytm)</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="w-5 h-5 bg-blue-500 text-white rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">2</span>
              <span>Scan the QR code or enter the UPI ID above</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="w-5 h-5 bg-blue-500 text-white rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">3</span>
              <span>Pay exactly ₹{amount}</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="w-5 h-5 bg-blue-500 text-white rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">4</span>
              <span>Wait for admin verification</span>
            </li>
          </ol>
        </div>

        {/* Timer */}
        <div className="text-center mb-6">
          <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-full ${
            countdown < 60 ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-600'
          }`}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path>
            </svg>
            <span className="text-sm font-medium">QR expires in {formatTime(countdown)}</span>
          </div>
        </div>

        {/* Waiting Message */}
        <div className="bg-yellow-50 border-2 border-yellow-200 rounded-2xl p-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-yellow-500 rounded-full flex items-center justify-center flex-shrink-0">
              <svg className="w-5 h-5 text-white animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path>
              </svg>
            </div>
            <div>
              <div className="font-semibold text-yellow-800">Please Do Not Close</div>
              <div className="text-sm text-yellow-700">This window will close automatically after admin verification</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default UPIQRCode;
